function __rlParse(raw) {
  var data = raw;
  if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) { return null; }
  }
  return (data && data.results) ? data.results : null;
}
function __rlItem(entry) {
  if (!entry) return null;
  // 榜单接口把漫画包在 comic 字段里，列表/搜索接口直接是漫画对象。
  var m = (entry.comic && entry.comic.path_word) ? entry.comic : entry;
  var id = m.path_word || '';
  if (!id) return null;
  var author = '';
  if (Array.isArray(m.author) && m.author.length > 0 && m.author[0]) {
    author = m.author[0].name || '';
  }
  var tags = [];
  if (Array.isArray(m.theme)) {
    for (var i = 0; i < m.theme.length; i++) {
      if (m.theme[i] && m.theme[i].name) tags.push(m.theme[i].name);
    }
  }
  var item = {
    id: id,
    title: m.name || id,
    cover: m.cover || '',
    author: author,
    tags: tags
  };
  if (m.datetime_updated) item.updatedAt = m.datetime_updated;
  return item;
}
function __rlList(raw) {
  var res = __rlParse(raw);
  if (!res || !res.list || typeof res.list.length !== 'number') return [];
  var out = [];
  for (var i = 0; i < res.list.length; i++) {
    var it = __rlItem(res.list[i]);
    if (it) out.push(it);
  }
  return out;
}

function parseList(raw, context) {
  return __rlList(raw);
}

