function parseDetail(raw, context) {
  var res = __rlParse(raw);
  var c = res ? res.comic : null;
  if (!c || !c.path_word) return null;
  var authors = [];
  if (Array.isArray(c.author)) {
    for (var i = 0; i < c.author.length; i++) {
      if (c.author[i] && c.author[i].name) authors.push(c.author[i].name);
    }
  }
  var tags = [];
  if (Array.isArray(c.theme)) {
    for (var j = 0; j < c.theme.length; j++) {
      if (c.theme[j] && c.theme[j].name) tags.push(c.theme[j].name);
    }
  }
  // 地区也是一种常见筛选维度，并入标签一起展示（如 韓國 / 日本）。
  if (c.region && c.region.display && tags.indexOf(c.region.display) < 0) {
    tags.push(c.region.display);
  }
  var item = {
    id: c.path_word,
    title: c.name || c.path_word,
    cover: c.cover || '',
    author: authors.join('、'),
    description: c.brief || '',
    status: (c.status && c.status.display) || '',
    tags: tags
  };
  if (c.datetime_updated) item.updatedAt = c.datetime_updated;
  return item;
}

