function parseImages(raw, context) {
  var res = __rlParse(raw);
  var ch = res ? res.chapter : null;
  if (!ch || !ch.contents) return [];
  var urls = [];
  for (var i = 0; i < ch.contents.length; i++) {
    var u = ch.contents[i] && ch.contents[i].url;
    if (u && typeof u === 'string' && u.length > 0) urls.push(u);
  }
  if (urls.length === 0) return [];
  // 部分章节的 contents 是乱序的，真实顺序由 words 数组给出（第 n 项为原索引）。
  var words = ch.words;
  if (words && words.length === urls.length) {
    var ordered = new Array(urls.length);
    var filled = true;
    for (var w = 0; w < words.length; w++) {
      var idx = words[w];
      if (typeof idx !== 'number' || idx < 0 || idx >= urls.length) { filled = false; break; }
      ordered[idx] = urls[w];
    }
    if (filled) {
      for (var f = 0; f < ordered.length; f++) {
        if (!ordered[f]) { filled = false; break; }
      }
      if (filled) return ordered;
    }
  }
  return urls;
}

