  var base = (context && context.baseUrl) ? context.baseUrl : '';
  if (base.endsWith('/')) base = base.slice(0, -1);
  var token = (context && context.token) ? context.token : '';
  return {
    __meta: true,
    __fetchUrl: base + '/api/v3/member/collect/comic',
    __fetchMethod: 'post',
    __fetchResponseType: 'text',
    __fetchBody: 'comic_id=' + encodeURIComponent(uuid) +
                 '&is_collect=1&authorization=Token+' + encodeURIComponent(token),
    __fetchHeaders: { 'Content-Type': 'application/x-www-form-urlencoded' },
    __processor: '__favPost'
  };
}
function __favPost(raw, context) {
  var data = raw;
  if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { data = null; } }
  if (!data || data.code !== 200) {
    throw new Error('收藏失败：' + ((data && data.message) ? data.message : '未知错误'));
  }
  return [{ id: '1', title: 'ok' }];
}
